source.exploreUrl:
@js:
(function() {
    var list = [];
    function buildUrl(categoryId, sex) {
        return "@js:\"https://gateway.kugou.com/v1/book/category_list?\" + getsign(\"fee_type=0&type=" + sex + "&show_type=0&category_id=" + categoryId + "&size=100&page=\" + page + \"&status=0\") + \",{\\\"headers\\\":{\\\"x-router\\\":\\\"longaudio.kugou.com\\\"}}\"";
    }
    function addItem(title, url) {
        list.push({
            title: title,
            url: url,
            style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.25 }
        });
    }
    function addTitle(title) {
        list.push({
            title: title,
            url: null,
            style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
        });
    }
    var maleCates = [
        {title:'都市', value:'61'}, {title:'玄幻', value:'63'},
        {title:'仙侠', value:'69'}, {title:'历史', value:'71'},
        {title:'科幻', value:'77'}, {title:'游戏', value:'75'},
        {title:'奇幻', value:'87'}, {title:'悬疑', value:'67'},
        {title:'武侠', value:'73'}, {title:'体育', value:'81'},
        {title:'军事', value:'65'}, {title:'二次元', value:'79'},
        {title:'现实', value:'111'}, {title:'短篇', value:'113'}
    ];
    var femaleCates = [
        {title:'现代言情', value:'105'}, {title:'古代言情', value:'99'},
        {title:'玄幻言情', value:'101'}, {title:'仙侠奇缘', value:'103'},
        {title:'浪漫青春', value:'107'}, {title:'科幻空间', value:'85'},
        {title:'悬疑侦探', value:'93'}, {title:'现实生活', value:'109'},
        {title:'短篇', value:'83'}
    ];
    addTitle('🔥 男生分类 🔥');
    maleCates.forEach(function(c) {
        addItem(c.title, buildUrl(c.value, 1));
    });
    addTitle('🌸 女生分类 🌸');
    femaleCates.forEach(function(c) {
        addItem(c.title, buildUrl(c.value, 2));
    });
    return JSON.stringify(list);
})();

source.jsLib:
function getsign(params) {
    var timestamp = Math.floor(new Date().getTime() / 1000);
    var base = "mid=1&userid=0&dfid=0&appid=1005&clientver=0&clienttime=" + timestamp + "&" + params;
    var str = c + a(base) + c;
    return "signature=" + b(str) + "&" + base;
}

var c = "OIlwieks28dk2k092lksi2UIkp";

function a(qs) {
    var params = qs.split('&');
    var obj = {};
    params.forEach(function(p) {
        var kv = p.split('=');
        obj[kv[0]] = kv[1] || '';
    });
    var keys = Object.keys(obj).sort();
    var result = keys.map(function(k) {
        return k + '=' + obj[k];
    });
    return result.join('');
}

function b(str) {
    try {
        var md = java.security.MessageDigest.getInstance("MD5");
        var bytes = new java.lang.String(str).getBytes("UTF-8");
        md.update(bytes);
        var digest = md.digest();
        var hex = "";
        for (var i = 0; i < digest.length; i++) {
            var x = digest[i] & 0xFF;
            if (x < 16) hex += "0";
            hex += x.toString(16);
        }
        return hex;
    } catch(e) {
        return "";
    }
}

