@js:
function login() {}

function toCa() {
    cookie.removeCookie("https://www.lofter.com");
   cookie.removeCookie("📖Lofter"); java.ajax("https://www.lofter.com/front/membership/store-vip/verify-phone");
    let token = source.getLoginHeaderMap().get("lofter-phone-login-auth");
    let co = "LOFTER-PHONE-LOGIN-AUTH=\"" + token + "\";LofterInnerBrowser=true;"

    co += cookie.getCookie("https://www.lofter.com");
    let headers = JSON.stringify({
        headers: {
            Cookie: co
        }
    });
    let verifyPhoneCheck = JSON.parse(java.ajax("https://www.lofter.com/newweb/phone/verifyPhoneCheck.json?_=" + Date.now() + "," + headers));
    if (verifyPhoneCheck.code == 200) {
        let phone = java.base64Decode(verifyPhoneCheck.data.cPhone);
        java.toast("当前验证手机号：\n" + phone);
        source.put("phone",phone);
        //发送验证码
        let imgurl = "https://www.lofter.com/lpt/photoCaptcha/getPhotoCaptcha.do?width=180&height=84&" + Date.now();
        let code = java.getVerificationCode(imgurl);
        let u = "https://www.lofter.com/lpt/getCaptchaPlus.do?_=" + Date.now();
        post = JSON.stringify({
            method: "POST",
            "body": "phone=" + phone + "&imageCode=" + code + "&clientType=0&sourceType=1&countryCode=86",headers: {Cookie: co}
        });
   //     java.log(post)
        let r = java.ajax(u + "," + post);
    //    java.log(r);
        java.toast(JSON.parse(r).desc)
    }
}

function cap(){
    //验证验证码
         try{
    let token = source.getLoginHeaderMap().get("lofter-phone-login-auth");
    let co = "LOFTER-PHONE-LOGIN-AUTH=\"" + token + "\";LofterInnerBrowser=true;"
    co += cookie.getCookie("https://www.lofter.com");

        let phone = String(source.get("phone"));
        java.toast("当前验证手机号：\n" + phone);
        u = "https://www.lofter.com/newweb/phone/checkPhoneCaptcha.json?_=" + Date.now();
        post = JSON.stringify({
            method: "POST",
            "body": {
                "countryCode": 86,
                "phone": phone,
                "captcha": result.get("账号风险验证码"),
                "device": String(java.androidId())
            }
        });
        //java.log(post)
         r =	java.post(u,JSON.stringify({
                "countryCode": 86,
                "phone": result.get("账号"),
                "captcha": result.get("账号风险验证码"),
                "device": String(java.androidId())
            }),{Cookie: String(co),"content-type":"application/json;charset=UTF-8"}).body();
     //	java.log(r);
        java.toast(JSON.parse(r).msg)
         }catch(e){
             java.log(e)
         }
}


function getCode() {
    try {
        let imgurl = "https://www.lofter.com/lpt/photoCaptcha/getPhotoCaptcha.do," + JSON.stringify({
            "method": "POST",
            "body": "width=270&height=126"
        });
        //	java.log(imgurl)
        java.toast("请输入图片验证码");
        let code = java.getVerificationCode(imgurl);
        let codeurl = "https://www.lofter.com/lpt/getCaptchaPlus.do," + JSON.stringify({
            "method": "POST",
            "body": "clientType=0&phone=" + result.get("账号") + "&sourceType=0&imageCode=" + code
        });
        java.toast(JSON.parse(java.ajax(codeurl)).desc)
        //	java.log(java.ajax(codeurl))
    } catch (e) {
        java.log(e)
    }
}

function toLogin(type) {
    let url = "https://www.lofter.com/lpt/login.do?product=lofter-android-8.3.20,";
    let phone = result ? result.get("账号") : "";
    let pwd = result ? result.get("密码[或短信验证码]") : "";
    let body = "";
    switch (type) {
        case 'phone':
            body = `deviceType=0&clientType=0&passport=${java.digestHex(pwd,"SHA-256")}&phone=${phone}&sourceType=0&type=0`
            break;

        case 'code':
            body = `deviceType=0&clientType=0&phone=${phone}&captcha=${pwd}&sourceType=0&type=1`
            break;

        case 'id':
            url = "https://www.lofter.com/lpt/account/login.do?product=lofter-android-8.3.20,";
            body = `password=${java.digestHex(pwd,"SHA-256")}&blogName=${phone}`;
            break;
    }

    let post = JSON.stringify({
        "method": "POST",
        "body": String(body)
    });
    //	java.log(post)
    let headers = {}
    let d = JSON.parse(java.ajax(url + post));
    java.toast(d.desc);

    if (d.result == 0) {
        headers["lofter-phone-login-auth"] = d.token;
        source.putLoginHeader(JSON.stringify(headers));
    } else if (type == "id" && d.status == 200) {

        headers["authorization"] = "ThirdParty " + d.token;
        source.putLoginHeader(JSON.stringify(headers));

    }
}

