}

function jsonToLrc(jsonText) {
    const {java} = this;

  var data = typeof jsonText === 'string' ? JSON.parse(jsonText) : jsonText;

  function pad(n, w) {
    if (w === undefined) w = 2;
    return String(Math.floor(n)).padStart(w, '0');
  }

  function toTimeTag(ms) {
    var totalSeconds = ms / 1000;
    var minutes = Math.floor(totalSeconds / 60);
    var seconds = totalSeconds % 60;
    return (
      pad(minutes) +
      ':' +
      pad(seconds, 2) +
      '.' +
      pad((seconds % 1) * 100, 2)
    );
  }

  var lines = [];
  for (var i = 0; i < data.length; i++) {
    var item = data[i];
    var timeTag = toTimeTag(item.time_begin);
    var text = item.text != null ? item.text : '';
    lines.push('[' + timeTag + ']' + text);
  }

  return lines.join('\n');
}


function getSvgCode() {
	  const {cache,source} = this;
	  let code =  cache.getFile(source.getKey()+"_guaner_svg") || cache.getFile("guaner_svg") || `<svg viewBox="0 0 1000 800" xmlns="http://www.w3.org/2000/svg">
    <path d="M865 100 h-600c-60 0-110 50-110 110v150l-120 80 120 80v150c0 60 50 110 110 110h600c60 0 110-50 110-110V210c0-60-50-110-110-110z  " fill="none" stroke="边" stroke-width="40"/>
    <text x="570" y="565" font-family="Roboto Condensed" text-anchor="middle" dominant-baseline="middle" font-size="420" font-weight="bold" fill="字">
      数量
    </text>
  </svg>`;
	  return String(code)
}

function getChapterSvgCode(){
    const {cache,source} = this;
