        comment.meta_right = [(x.likeCount?'<i class="far fa-thumbs-up"></i>'+x.likeCount:"")];
        comment.card_footer_extra = "${t}"=="1"?x.quote:"";
        comment.image_grid = x.images?x.images.map(x=>x.orign):[];
        comment.replyNum = x.l2Count;
        commentList.push(comment)
    }

    return commentList
}
`;

