function getSvg(totalnum) {
    let {
        java,cache
    } = this;

    try{
    let co = "#" + String(java.getReadBookConfigMap()["textColor"]).match(/.{6}$/)[0];
    if (String(java.getThemeConfigMap()["isNightTheme"]) === "true") {
        co = "#" + String(java.getReadBookConfigMap()["textColorNight"]).match(/.{6}$/)[0];
    }
    let color = [co, co];
    totalnum = totalnum > 999 ? "999" : totalnum;
    let dpstyle = this.getSvgCode();

    if(totalnum === 0){
        dpstyle = this.getChapterSvgCode();
    }

    let svg = dpstyle.replace(/"边"/g,`"${color[0]}"`)
    .replace(/"字"/g,`"${color[1]}"`)
    .replace(/数量/g,totalnum);
    return "data:image/svg+xml;base64," + java.base64Encode(svg);
    }catch(e){
        java.log(e)
    }
}


